part of 'palette_bloc.dart';

/// The status of the [PaletteBloc].
enum PaletteStatus() {
  /// Nothing has been loaded yet.
  initial,

  /// The palette is being loaded.
  loading,

  /// The palette can be edited.
  ready,

  /// The palette is being saved.
  saving,

  /// The palette was saved and its code generated.
  saved,

  /// The palette was saved, but its code was not generated because a file
  /// that was not generated by the editor is in the way.
  codeConflict,

  /// The palette was saved, but generating its code failed.
  codeFailure,

  /// Something went wrong while loading or saving.
  failure;

  /// Whether the palette was saved, even if its code was not generated.
  bool get isSaved =>
      this == saved || this == codeConflict || this == codeFailure;
}

/// {@template palette_entry}
/// A color of the palette being edited.
/// {@endtemplate}
final class const PaletteEntry({
  /// Identifies the entry while it is edited, even when renamed.
  required final int id,

  /// The color, with the name and value being edited.
  required final PaletteColor color,

  /// The name of the color in the saved palette, or `null` for a color
  /// added since. Components reference colors by this name.
  final String? savedName,
}) extends Equatable {
  /// {@macro palette_entry}
  this;

  /// Returns a copy of this entry with [color] replaced.
  PaletteEntry copyWith({PaletteColor? color}) {
    return PaletteEntry(
      id: id,
      color: color ?? this.color,
      savedName: savedName,
    );
  }

  @override
  List<Object?> get props => [id, color, savedName];
}

/// {@template palette_state}
/// The state of the [PaletteBloc].
/// {@endtemplate}
final class const PaletteState({
  /// The current status.
  final PaletteStatus status = PaletteStatus.initial,

  /// The colors being edited, in order.
  final List<PaletteEntry> entries = const [],

  /// The palette as it was last saved.
  final Palette savedPalette = const Palette(),

  /// The names of the components that use each palette color.
  final Map<String, List<String>> usage = const {},
}) extends Equatable {
  /// {@macro palette_state}
  this;

  /// The palette being edited.
  Palette get palette =>
      Palette(colors: [for (final entry in entries) entry.color]);

  /// Whether the palette has changes that were not saved yet.
  bool get hasChanges => palette != savedPalette;

  /// Whether the palette is loaded and not being saved.
  bool get isEditable =>
      status != PaletteStatus.initial &&
      status != PaletteStatus.loading &&
      status != PaletteStatus.saving;

  /// Whether the palette can be saved: every name is valid (see
  /// [Palette.validateColorName]) and it is not loading or being saved.
  bool get canSave => isEditable && palette.isValid;

  /// The names of the components that use the color of [entry]. A color in
  /// use can't be renamed or removed, which would break their references.
  List<String> usersOf(PaletteEntry entry) {
    final savedName = entry.savedName;
    return savedName == null ? const [] : usage[savedName] ?? const [];
  }

  /// Returns a copy of this state with the given fields replaced.
  PaletteState copyWith({
    PaletteStatus? status,
    List<PaletteEntry>? entries,
    Palette? savedPalette,
    Map<String, List<String>>? usage,
  }) {
    return PaletteState(
      status: status ?? this.status,
      entries: entries ?? this.entries,
      savedPalette: savedPalette ?? this.savedPalette,
      usage: usage ?? this.usage,
    );
  }

  @override
  List<Object> get props => [status, entries, savedPalette, usage];
}
